package engine
import("os";"fmt";"testing";"math/bits";"bytes")
func TestMetadataProbe(t *testing.T) {for _, name:=range []string{"dickens","webster","nci","xml","sao","reymont","mr","x-ray"} {data,e:=os.ReadFile("/mnt/data/jlz_round6/corpus/"+name);if e!=nil {continue}; var rawlen,rawd,packlen,packd,slotPackLen,slotPackD int64;var deltaD int64; var nblk, commands int; for at:=0; at<len(data)&&nblk<30;at+=stage3BlockSize {end:=min(at+stage3BlockSize,len(data));b:=data[at:end];if !stage3MatchPotential(b){continue}; tok,e:=tokenizeMatchV2(b);if e!=nil {t.Fatal(e)};st,e:=splitMatchTokens(tok,len(b));if e!=nil{t.Fatal(e)}; nblk++;commands+=st.ncommands; rawlen+=int64(len(st.lengths));rawd+=int64(len(st.distances));packlen+=int64(len(packStream(st.lengths)));packd+=int64(len(packStream(st.distances)));slotPackLen+=int64(packSlots(st.lengths));slotPackD+=int64(packSlots(st.distances));deltaD+=int64(packSlotsDelta(st.distances)) };fmt.Printf("%s blocks=%d commands=%d lengths raw/packed/slots=%d/%d/%d dist=%d/%d/%d/delta%d\n",name,nblk,commands,rawlen,packlen,slotPackLen,rawd,packd,slotPackD,deltaD)}}
func packSlots(dat []byte) int {r:=bytes.NewReader(dat);var slot []byte;bitsN:=0;for r.Len()>0 {v,e:=readVar(r);if e!=nil{return len(dat)+1000};n:=bits.Len64(v);slot=append(slot,byte(n));bitsN+=max(n-1,0)};return len(packStream(slot))+(bitsN+7)/8+5}

func packSlotsDelta(dat []byte) int {r:=bytes.NewReader(dat);var slot []byte;bitsN:=0;var prev uint64;for r.Len()>0 {v,e:=readVar(r);if e!=nil{return len(dat)+1000}; d:=int64(v)-int64(prev);zz:=uint64(d<<1)^uint64(d>>63); n:=bits.Len64(zz);slot=append(slot,byte(n));bitsN+=max(n-1,0);prev=v};return len(packStream(slot))+(bitsN+7)/8+5}
